import {
  Group, Mesh, PlaneGeometry, BoxGeometry,
  MeshStandardNodeMaterial, MeshBasicNodeMaterial,
  Texture, RepeatWrapping, LinearFilter,
  Clock, Vector3, Color, AdditiveBlending
} from 'three/webgpu';
import {
  float, vec2, vec3, vec4, mix, step, smoothstep,
  time, uniform, uv, texture, positionWorld,
  screenUV, cameraPosition, normalize, dot,
  reflect, pow, length, max, abs, sin, cos,
  Fn, If, Loop, Break
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Extract config
  const colors = config.colors || config.intent?.visualSpec?.colors || {};
  const textContent = config.textContent || config.intent?.visualSpec?.textContent || [];
  const effects = config.effects || config.intent?.visualSpec?.effects || '';
  const imageUrl = config.imageUrl || '';

  // Determine tier
  const tier = ctx.tier || 'T1';

  // Store cleanup functions
  const cleanups = [];
  const timelines = [];

  // Create image plate variant URLs (distinct crops from base image)
  const plateVariants = [
    imageUrl,
    imageUrl.replace('.png', '-crop-1.png'),
    imageUrl.replace('.png', '-crop-2.png'),
    imageUrl.replace('.png', '-crop-3.png'),
    imageUrl.replace('.png', '-crop-4.png'),
    imageUrl.replace('.png', '-crop-5.png'),
  ];

  // Create backdrop
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();

  // Build gradient texture procedurally
  const gradientFn = Fn(() => {
    const vUv = uv();
    const color0 = vec3(0.043, 0.043, 0.063); // #0b0b10
    const color1 = vec3(0.078, 0.078, 0.102); // #14141a
    const gradient = mix(color0, color1, vUv.y);
    return vec4(gradient, 1.0);
  });

  backdropMat.colorNode = gradientFn();
  backdropMat.depthWrite = false;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Parse effects to get configuration parameters
  const plateWidth = 1.9;
  const plateHeight = 1.2;
  const pitch = 1.5;
  const totalPlates = 6;
  const loopHeight = totalPlates * pitch; // 9.0 units
  const columnOffsetX = 0.9;
  const bevelSize = 0.03;
  const accentStripWidth = 0.03;

  // Parse scroll behavior from effects string
  const scrollSpeedMatch = effects.match(/([\d.]+)\s*units\s*per\s*viewport\s*scroll/);
  const scrollSpeed = scrollSpeedMatch ? parseFloat(scrollSpeedMatch[1]) * 1.5 : 1.5;
  const dampingMatch = effects.match(/damping\s*([\d.]+)/);
  const damping = dampingMatch ? parseFloat(dampingMatch[1]) : 0.12;

  // Parse fly-through depth
  const depthMatch = effects.match(/([\d.]+)\s*units\s*deeper/);
  const flyThroughDepth = depthMatch ? parseFloat(depthMatch[1]) : 2.5;

  // Create plates container
  const platesContainer = new Group();
  platesContainer.position.x = columnOffsetX;
  group.add(platesContainer);

  // Create headline text
  const headlineItem = textContent.find(t => 
    t.role === 'headline' || t.text === 'Inside the atelier'
  );
  if (headlineItem) {
    const headline = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: headlineItem.typography?.fontSize || 68,
      color: colors.paper || '#e8ecf2',
      align: 'left'
    });
    headline.position.set(-1.6, 1.9, 0);
    headline.scale.set(0.002, 0.002, 0.002);
    group.add(headline);

    // Animate headline in
    headline.opacity = 0;
    const tl = gsap.timeline({ delay: 0.3 });
    tl.to(headline, { 
      opacity: 1, 
      y: 0, 
      duration: 0.7, 
      ease: 'power3.out' 
    });
    timelines.push(tl);
  }

  // Create caption items and associate with plates
  const captionItems = textContent.filter(t => 
    t.role === 'caption' || t.typography?.fontSize <= 24
  );

  // Create plate meshes (6 plates)
  const plateMeshes = [];
  const captionMeshes = [];
  const focusState = []; // Track focus state for each plate

  // Load textures first
  const texturePromises = plateVariants.map(url => {
    if (url && !url.includes('undefined')) {
      return ctx.textureLoader.loadTexture(url).catch(() => null);
    }
    return Promise.resolve(null);
  });

  // Wait for all textures to load then build plates
  return Promise.all(texturePromises).then(textures => {
    for (let i = 0; i < totalPlates; i++) {
      const plateGroup = new Group();
      const yPos = -i * pitch;
      plateGroup.position.y = yPos;

      // Calculate wrapping for looping (extend beyond visible range)
      // Plates exist in range [-3 * pitch, 3 * pitch] for seamless loop

      // Create plate main surface
      const plateGeo = new PlaneGeometry(plateWidth, plateHeight);
      const plateMat = new MeshStandardNodeMaterial();
      plateMat.roughness = 0.6;
      plateMat.metalness = 0.1;
      plateMat.clearcoat = 0.1;

      // Apply texture if available
      const tex = textures[i];
      if (tex) {
        plateMat.map = tex;
        plateMat.needsUpdate = true;
      } else {
        // Fallback: procedural filmic gradient
        const filmGradFn = Fn(() => {
          const vUv = uv();
          const vignette = smoothstep(0.7, 0.0, length(vUv - 0.5) * 1.2);
          const base = vec3(0.15, 0.12, 0.1);
          const highlight = vec3(0.25, 0.22, 0.18);
          const gradient = mix(base, highlight, smoothstep(0.3, 0.7, vUv.y));
          const final = mix(gradient, vec3(0.08, 0.07, 0.06), 1.0 - vignette);
          return vec4(final, 1.0);
        });
        plateMat.colorNode = filmGradFn();
      }

      const plate = new Mesh(plateGeo, plateMat);
      plateGroup.add(plate);

      // Create bevel frame
      const bevelGeo = new BoxGeometry(plateWidth + bevelSize * 2, plateHeight + bevelSize * 2, 0.03);
      const bevelMat = new MeshStandardNodeMaterial();
      bevelMat.color = new Color(colors.ink || '#16161d');
      bevelMat.roughness = 0.5;
      bevelMat.metalness = 0.5;

      const bevel = new Mesh(bevelGeo, bevelMat);
      bevel.position.z = -0.015;
      plateGroup.add(bevel);

      // Create accent strip (left edge)
      const accentGeo = new PlaneGeometry(accentStripWidth, plateHeight);
      const accentMat = new MeshBasicNodeMaterial();
      accentMat.color = new Color(colors.accent || '#ff2a38');

      // We'll control emissive for focus by a uniform
      const accentEmissive = uniform(0.0);
      const accentGlowFn = Fn(() => {
        const baseColor = vec3(1.0, 0.165, 0.22);
        return vec4(baseColor * (0.5 + accentEmissive * 0.5), 1.0);
      });
      accentMat.colorNode = accentGlowFn();

      const accentStrip = new Mesh(accentGeo, accentMat);
      accentStrip.position.x = -plateWidth / 2 - bevelSize;
      accentStrip.position.z = 0.015;
      accentStrip.scale.x = 1.0;
      plateGroup.add(accentStrip);

      // Store reference for focus animation
      focusState.push({
        accentEmissive,
        plate,
        accentStrip,
        plateGroup,
        isFocused: false
      });

      // Add caption for this plate
      const captionItem = captionItems[i];
      if (captionItem) {
        const caption = ctx.fontAtlas.createText(captionItem.text, {
          fontSize: captionItem.typography?.fontSize || 18,
          color: colors.paper || '#e8ecf2',
          align: 'left',
          letterSpacingPx: (captionItem.typography?.letterSpacing || 0.08) * 100
        });
        caption.position.set(-plateWidth / 2 - bevelSize - 0.3, 0, 0);
        caption.rotation.y = 0;
        caption.scale.set(0.0015, 0.0015, 0.0015);
        caption.name = `caption-${i}`;
        plateGroup.add(caption);
        captionMeshes.push(caption);

        // Caption fades in when focused
        caption.visible = false;
      }

      platesContainer.add(plateGroup);
      plateMeshes.push(plateGroup);
    }

    // Create initial scroll position tracker
    const scrollState = {
      currentY: 0,
      targetY: 0,
      velocity: 0,
      isAnimating: false,
      scrollPercent: 0
    };

    // Handle scroll events
    const handleScroll = (e) => {
      if (!e || !e.deltaY) return;

      const delta = e.deltaY * 0.01;
      scrollState.targetY += delta * scrollSpeed;
      scrollState.velocity = delta * scrollSpeed;

      // Clamp target to loop range
      const maxScroll = loopHeight;
      scrollState.targetY = ((scrollState.targetY % maxScroll) + maxScroll) % maxScroll;

      // Trigger weighted settle
      if (scrollState.rafId) cancelAnimationFrame(scrollState.rafId);

      const animateScroll = () => {
        // Apply damping
        scrollState.velocity *= (1 - damping);
        scrollState.currentY += scrollState.velocity * 0.016;

        // Loop current Y
        scrollState.currentY = ((scrollState.currentY % loopHeight) + loopHeight) % loopHeight;

        // Update plate positions
        updatePlatePositions(scrollState.currentY);

        // Update fly-through (camera depth)
        const depthProgress = (scrollState.currentY / loopHeight) * 2 - 1; // -1 to 1
        // This would normally affect camera z, but we need to communicate up
        // For now, we'll use a uniform on the group to signal depth
        group.userData.cameraDepthOffset = depthProgress * flyThroughDepth * 0.5;
        ctx.emit('camera-depth-offset', { offset: group.userData.cameraDepthOffset });

        // Check if settled
        if (Math.abs(scrollState.velocity) > 0.001) {
          scrollState.rafId = requestAnimationFrame(animateScroll);
        } else {
          scrollState.isAnimating = false;
          // Final weighted settle
          const settleTl = gsap.to(scrollState, {
            velocity: 0,
            duration: 0.9,
            ease: 'power4.out',
            onUpdate: () => {
              scrollState.currentY += scrollState.velocity * 0.016;
              scrollState.currentY = ((scrollState.currentY % loopHeight) + loopHeight) % loopHeight;
              updatePlatePositions(scrollState.currentY);
            }
          });
          timelines.push(settleTl);
        }
      };

      if (!scrollState.isAnimating) {
        scrollState.isAnimating = true;
        scrollState.rafId = requestAnimationFrame(animateScroll);
      }
    };

    // Store handler
    group.userData.handlers = {
      scroll: handleScroll
    };

    // Helper to update plate positions
    const updatePlatePositions = (scrollY) => {
      for (let i = 0; i < totalPlates; i++) {
        // Calculate base position with looping
        let yPos = -i * pitch - scrollY;

        // Wrap to loop range [-loopHeight/2, loopHeight/2]
        while (yPos < -loopHeight / 2) yPos += loopHeight;
        while (yPos > loopHeight / 2) yPos -= loopHeight;

        plateMeshes[i].position.y = yPos;

        // Check focus (nearest to y=0)
        const distToZero = Math.abs(yPos);
        const isFocused = distToZero < pitch / 2;

        const state = focusState[i];

        if (isFocused && !state.isFocused) {
          // Focus this plate
          state.isFocused = true;

          // Scale up
          gsap.to(state.plate.scale, {
            x: 1.06,
            y: 1.06,
            duration: 0.35,
            ease: 'cubic-bezier(0.215,0.61,0.355,1)'
          });

          // Glow accent strip
          gsap.to(state.accentEmissive, {
            value: 1.4,
            duration: 0.35,
            ease: 'cubic-bezier(0.215,0.61,0.355,1)'
          });

          // Show caption for this plate
          const caption = plateMeshes[i].getObjectByName(`caption-${i}`);
          if (caption) {
            caption.visible = true;
            caption.opacity = 0;
            gsap.to(caption, {
              opacity: 1,
              x: -plateWidth / 2 - bevelSize - 0.3,
              duration: 0.35,
              ease: 'power2.out'
            });
          }

          // Hide other captions
          for (let j = 0; j < totalPlates; j++) {
            if (j !== i) {
              const otherState = focusState[j];
              otherState.isFocused = false;

              gsap.to(otherState.plate.scale, {
                x: 1.0,
                y: 1.0,
                duration: 0.35,
                ease: 'cubic-bezier(0.215,0.61,0.355,1)'
              });

              gsap.to(otherState.accentEmissive, {
                value: 0.0,
                duration: 0.35,
                ease: 'cubic-bezier(0.215,0.61,0.355,1)'
              });

              const otherCaption = plateMeshes[j].getObjectByName(`caption-${j}`);
              if (otherCaption) {
                gsap.to(otherCaption, {
                  opacity: 0,
                  duration: 0.2,
                  ease: 'power2.out',
                  onComplete: () => { otherCaption.visible = false; }
                });
              }
            }
          }
        }
      }
    };

    // Initialize plate positions
    updatePlatePositions(0);

    // Add rim light for machined effect
    const rimLight = new ctx.THREE.DirectionalLight(colors.accent || '#ff2a38', 0.8);
    rimLight.position.set(-3, 2, -1);
    group.add(rimLight);

    const keyLight = new ctx.THREE.DirectionalLight(colors.paper || '#e8ecf2', 1.2);
    keyLight.position.set(2, 3, 4);
    group.add(keyLight);

    const fillLight = new ctx.THREE.AmbientLight(0x444466, 0.6);
    group.add(fillLight);

    // Apply cinematic primitives
    let flyThroughResult = null;
    if (config.cinematicPrimitives) {
      for (const prim of config.cinematicPrimitives) {
        if (prim.name === 'fly-through' && prim.trigger === 'scroll') {
          flyThroughResult = ctx.primitives['fly-through'](
            group, 
            { 
              depthUnits: flyThroughDepth,
              scrollRange: loopHeight,
              scrollState: scrollState
            }
          );
          if (flyThroughResult) {
            cleanups.push(flyThroughResult.cleanup);
            if (flyThroughResult.timeline) {
              timelines.push(flyThroughResult.timeline);
            }
          }
        }
      }
    }

    // Store cleanup
    group.userData.cleanup = () => {
      // Kill all GSAP timelines
      timelines.forEach(tl => {
        if (tl.kill) tl.kill();
      });

      // Cancel animation frame
      if (scrollState.rafId) {
        cancelAnimationFrame(scrollState.rafId);
      }

      // Run primitive cleanups
      cleanups.forEach(fn => {
        if (typeof fn === 'function') fn();
      });

      // Dispose geometries
      backdropGeo.dispose();
      backdropMat.dispose();

      // Dispose plate resources
      for (let i = 0; i < totalPlates; i++) {
        const plateGroup = plateMeshes[i];
        plateGroup.children.forEach(child => {
          if (child.isMesh) {
            child.geometry?.dispose();
            child.material?.dispose();
          }
        });
      }
    };

    return group;
  });
}
